import fcntl
import os
import subprocess

from taf.internal.execution.base import ProcessFactory
from .local_process import LocalProcess, LocalInputStream, LocalOutputStream, LocalErrorStream


class LocalProcessFactory(ProcessFactory):
    def create_process(self, command):
        popen = self._create_popen(command)
        stdin = self._create_local_input_stream(file=popen.stdin)
        stdout = self._create_local_output_stream(file=popen.stdout)
        stderr = self._create_local_error_stream(file=popen.stderr)
        return LocalProcess(
            command=command,
            stdin=stdin,
            stdout=stdout,
            stderr=stderr,
            popen=popen)

    def _create_popen(self, command):
        popen = subprocess.Popen(
            command,
            bufsize=0,
            shell=True,
            executable="/bin/bash",
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE)
        stdout_fd = popen.stdout.fileno()
        stdout_flags = fcntl.fcntl(stdout_fd, fcntl.F_GETFL)
        fcntl.fcntl(stdout_fd, fcntl.F_SETFL, stdout_flags | os.O_NONBLOCK)
        stderr_fd = popen.stdout.fileno()
        stderr_flags = fcntl.fcntl(stderr_fd, fcntl.F_GETFL)
        fcntl.fcntl(stderr_fd, fcntl.F_SETFL, stderr_flags | os.O_NONBLOCK)
        return popen

    def _create_local_input_stream(self, file):
        return LocalInputStream(file=file)

    def _create_local_output_stream(self, file):
        return LocalOutputStream(file=file)

    def _create_local_error_stream(self, file):
        return LocalErrorStream(file=file)
